50	    pub fn is_internal(&self, name: &str, version: &str) -> Option<PackageName> {
51	        // If link_workspace_packages isn't set any version without workspace protocol
52	        // is considered external.
53	        if !self.link_workspace_packages && !version.starts_with("workspace:") {
54	            return None;
55	        }
56	        let workspace_specifier = WorkspacePackageSpecifier::new(version)
57	            .unwrap_or(WorkspacePackageSpecifier::Alias(name));
58	        let (workspace_name, info) = self.find_package(workspace_specifier)?;
59	        let is_internal = DependencyVersion::new(version).matches_workspace_package(
60	            // This is the current Go behavior, in the future we might not want to paper over a
61	            // missing version
62	            info.package_json.version.as_deref().unwrap_or_default(),
63	            self.workspace_dir,
64	            self.repo_root,
65	        );
66	
67	        match is_internal {
68	            true => Some(workspace_name),
69	            false => None,
70	        }
71	    }
