104	    fn workspace(&self, path: &AnchoredSystemPath) -> Option<(&PackageName, &PackageInfo)> {
105	        let name = self.path_index.0.get(path)?;
106	        let info = self.workspaces.get(name)?;
107	        Some((name, info))
108	    }
109	}
