140	impl<'a> DependencyVersion<'a> {
141	    fn new(qualified_version: &'a str) -> Self {
142	        qualified_version.split_once(':').map_or(
143	            Self {
144	                protocol: None,
145	                version: qualified_version,
146	            },
147	            |(protocol, version)| Self {
148	                protocol: Some(protocol),
149	                version,
150	            },
151	        )
152	    }
