154	    fn is_external(&self) -> bool {
155	        // The npm protocol for yarn by default still uses the workspace package if the
156	        // workspace version is in a compatible semver range. See https://github.com/yarnpkg/berry/discussions/4015
157	        // For now, we will just assume if the npm protocol is being used and the
158	        // version matches its an internal dependency which matches the existing
159	        // behavior before this additional logic was added.
160	
161	        // TODO: extend this to support the `enableTransparentWorkspaces` yarn option
162	        self.protocol.is_some_and(|p| p != "npm")
163	    }
164	
165	    fn matches_workspace_package(
166	        &self,
167	        package_version: &str,
168	        cwd: &AbsoluteSystemPath,
169	        root: &AbsoluteSystemPath,
170	    ) -> bool {
171	        match self.protocol {
172	            Some("workspace") => {
173	                // TODO: Since support at the moment is non-existent for workspaces that contain
174	                // multiple versions of the same package name, just assume its a
175	                // match and don't check the range for an exact match.
176	                true
177	            }
178	            Some("file") | Some("link") => {
179	                // Default to internal if we have the package but somehow cannot get the path
180	                RelativeUnixPathBuf::new(self.version)
181	                    .map(|file_path| cwd.join_unix_path(file_path))
182	                    .map_or(true, |dep_path| root.contains(&dep_path))
183	            }
184	            Some(_) if self.is_external() => {
185	                // Other protocols are assumed to be external references ("github:", etc)
186	                false
187	            }
