393	    fn resolve_dependency(
394	        &self,
395	        locator: &Locator,
396	        name: &str,
397	        range: &str,
398	    ) -> Result<Descriptor<'static>, Error> {
399	        // Handle catalog: protocol (Yarn 4+)
400	        let resolved_range = if !self.catalogs.is_empty() && range.starts_with("catalog:") {
401	            let catalog_spec = &range["catalog:".len()..];
402	            // catalog: with no name uses the default catalog
403	            let catalog_name = if catalog_spec.is_empty() {
404	                "default"
405	            } else {
406	                catalog_spec
407	            };
408	
409	            // Look up the version in the specified catalog
410	            self.catalogs
411	                .get(catalog_name)
412	                .and_then(|catalog| catalog.get(name))
413	                .map(|version| version.as_str())
414	                .ok_or_else(|| Error::MissingCatalogEntry {
415	                    name: name.to_string(),
416	                    catalog: catalog_name.to_string(),
417	                })?
418	        } else {
419	            range
420	        };
421	
422	        let mut dependency = Descriptor::new(name, resolved_range)?;
423	        // If there's no protocol we attempt to find a known one
424	        if dependency.protocol().is_none()
425	            && let Some(range) = self.resolver.get(&dependency)
426	        {
427	            dependency.range = range.to_string().into();
428	        }
