128	    pub fn new(lockfile: LockfileData, manifest: Option<BerryManifest>) -> Result<Self, Error> {
129	        let mut patches = Map::new();
130	        let mut locator_package = Map::new();
131	        let mut descriptor_locator = Map::new();
132	        let mut resolver = DescriptorResolver::default();
133	        let mut workspace_path_to_locator = HashMap::new();
134	        for (key, package) in &lockfile.packages {
135	            let locator = Locator::try_from(package.resolution.as_str())?;
136	
137	            if locator.patch_file().is_some() {
138	                let original_locator = locator
139	                    .patched_locator()
140	                    .ok_or_else(|| Error::PatchMissingOriginalLocator(locator.as_owned()))?;
141	                patches.insert(original_locator.as_owned(), locator.as_owned());
142	            }
143	
144	            locator_package.insert(locator.as_owned(), package.clone());
145	
146	            if let Some(path) = locator.reference.strip_prefix("workspace:") {
147	                workspace_path_to_locator.insert(path.to_string(), locator.as_owned());
148	            }
149	
150	            for descriptor in Descriptor::from_lockfile_key(key) {
151	                let descriptor = descriptor?;
152	                if let Some(other) = resolver.insert(&descriptor) {
153	                    Err(Error::DescriptorCollision {
154	                        descriptor: descriptor.clone().into_owned(),
155	                        other,
156	                    })?;
157	                }
158	                descriptor_locator.insert(descriptor.into_owned(), locator.as_owned());
159	            }
160	        }
161	
162	        let (overrides, catalogs) = if let Some(manifest) = manifest {
163	            manifest.into_parts()?
164	        } else {
165	            (Map::new(), Map::new())
166	        };
167	
168	        let mut this = Self {
169	            data: lockfile,
170	            resolutions: descriptor_locator,
171	            locator_package,
172	            resolver,
173	            patches,
174	            overrides,
175	            extensions: Default::default(),
176	            workspace_path_to_locator,
177	            catalogs: Arc::new(catalogs),
178	        };
179	
180	        this.populate_extensions()?;
181	
182	        Ok(this)
183	    }
