185	    fn populate_extensions(&mut self) -> Result<(), Error> {
186	        let mut possible_extensions: HashSet<_> = self
187	            .resolutions
188	            .keys()
189	            .filter(|descriptor| matches!(descriptor.protocol(), Some("npm")))
190	            .collect();
191	        for (locator, package) in &self.locator_package {
192	            for (name, range) in package.dependencies.iter().flatten() {
193	                let mut descriptor = self.resolve_dependency(locator, name, range.as_ref())?;
194	                if descriptor.protocol().is_none()
195	                    && let Some(range) = self.resolver.get(&descriptor)
196	                {
197	                    descriptor.range = range.into();
198	                }
199	                possible_extensions.remove(&descriptor);
200	            }
201	
202	            // For Yarn 4, remove any patch sources that are accounted for by a patch
203	            if let Some(Locator { ident, reference }) = locator.patched_locator() {
204	                possible_extensions.remove(&Descriptor {
205	                    ident,
206	                    range: reference,
207	                });
208	            }
209	        }
210	
211	        self.extensions.extend(
212	            possible_extensions
213	                .into_iter()
214	                .map(|desc| desc.clone().into_owned()),
215	        );
216	        Ok(())
217	    }
