219	    // Helper function for inverting the resolution map
220	    fn locator_to_descriptors(&self) -> HashMap<&Locator<'static>, HashSet<&Descriptor<'static>>> {
221	        let mut reverse_lookup: HashMap<&Locator, HashSet<&Descriptor>> =
222	            HashMap::with_capacity(self.locator_package.len());
223	
224	        for (descriptor, locator) in &self.resolutions {
225	            reverse_lookup
226	                .entry(locator)
227	                .or_default()
228	                .insert(descriptor);
229	        }
230	
231	        reverse_lookup
232	    }
