234	    /// Constructs a new lockfile data ready to be serialized
235	    pub fn lockfile(&self) -> Result<LockfileData, Error> {
236	        let mut packages = Map::new();
237	        let mut metadata = self.data.metadata.clone();
238	        let reverse_lookup = self.locator_to_descriptors();
239	
240	        for (locator, descriptors) in reverse_lookup {
241	            let mut descriptors = descriptors
242	                .into_iter()
243	                .map(|d| d.to_string())
244	                .collect::<Vec<_>>();
245	            descriptors.sort();
246	            let key = descriptors.join(", ");
247	
248	            let package = self
249	                .locator_package
250	                .get(locator)
251	                .ok_or_else(|| Error::MissingPackageForLocator(locator.as_owned()))?;
252	            packages.insert(key, package.clone());
253	        }
254	
255	        // Yarn v6 (Berry 3.x) strips cacheKey when a pruned subgraph contains
256	        // only workspace packages (no checksums). Yarn v8 (Berry 4.x) always
257	        // keeps it. Match each version's behavior so frozen installs pass.
258	        if metadata.version == "6" {
259	            let has_checksum = packages.values().any(|pkg| pkg.checksum.is_some());
260	            if !has_checksum {
261	                metadata.cache_key = None;
262	            }
263	        }
264	
265	        Ok(LockfileData { metadata, packages })
266	    }
