268	    /// Produces a new lockfile containing only the given workspaces and
269	    /// packages
270	    fn subgraph(
271	        &self,
272	        workspace_packages: &[String],
273	        packages: &[String],
274	    ) -> Result<BerryLockfile, Error> {
275	        let reverse_lookup = self.locator_to_descriptors();
276	
277	        let mut resolutions = Map::new();
278	        let mut patches = Map::new();
