11	#[derive(Debug, Clone, Hash, PartialEq, Eq, PartialOrd, Ord)]
12	struct Key {
13	    ident: Ident<'static>,
14	    range: String,
15	}
16	
17	#[derive(Debug, Clone, Hash, PartialEq, Eq, PartialOrd, Ord, Default)]
18	struct Entry {
19	    without: Option<String>,
20	    with: Option<RangeAndProtocol>,
21	}
22	
23	#[derive(Debug, Clone, Hash, PartialEq, Eq, PartialOrd, Ord, Default)]
24	struct RangeAndProtocol {
25	    protocol: String,
26	    range: String,
27	}
28	
29	impl DescriptorResolver {
30	    /// Add a descriptor to the resolver
31	    pub fn insert(&mut self, descriptor: &Descriptor) -> Option<String> {
32	        let key = Key::new(descriptor)?;
33	        let entry = self.mapping.entry(key).or_default();
34	        entry.insert_descriptor(descriptor)
35	    }
36	
37	    /// If given a descriptor without a protocol it will return all matching
38	    /// descriptors with a protocol
39	    pub fn get(&self, descriptor: &Descriptor) -> Option<&str> {
40	        let key = Key::new(descriptor)?;
41	        self.mapping.get(&key).and_then(|e| e.get(descriptor))
42	    }
43	}
