45	impl Key {
46	    fn new(desc: &Descriptor) -> Option<Self> {
47	        let ident = desc.ident.to_owned();
48	        let range = Descriptor::strip_protocol(desc.range()?).to_string();
49	        Some(Key { ident, range })
50	    }
51	}
52	
53	impl Entry {
54	    // Insert the given descriptor's range into the correct slot depending if it is
55	    // with or without a protocol
56	    fn insert_descriptor(&mut self, descriptor: &Descriptor) -> Option<String> {
57	        let range = descriptor.range()?.to_string();
58	        match descriptor.protocol() {
59	            Some(protocol) => {
60	                // Yarn 4 made the default npm protocol explicit in the lockfile.
61	                // In order to return the more specific protocol we avoid overwriting other
62	                // protocols with the now explicit npm protocol.
63	                if protocol != "npm" || self.with.is_none() {
64	                    match self.with.replace(RangeAndProtocol {
65	                        range,
66	                        protocol: protocol.to_string(),
67	                    }) {
68	                        // We only return an ejected range if the protocol isn't the default npm
69	                        // protocol
70	                        Some(RangeAndProtocol { range, protocol }) if protocol != "npm" => {
71	                            Some(range)
72	                        }
73	                        _ => None,
74	                    }
75	                } else {
76	                    None
77	                }
78	            }
79	            None => self.without.replace(range),
80	        }
81	    }
82	
83	    fn get(&self, descriptor: &Descriptor) -> Option<&str> {
84	        // We only return the without protocol range if `without` is present
85	        // and the given descriptor is also without a protocol
86	        if self.without.is_some() && descriptor.protocol().is_none() {
87	            self.without.as_deref()
88	        } else {
89	            self.with.as_ref().map(|x| x.range.as_str())
90	        }
91	    }
92	}
